export type HelpGuideCategory =
  | 'getting-started'
  | 'data'
  | 'carbon'
  | 'compliance'
  | 'reporting'
  | 'finance'
  | 'enterprise';

export interface HelpFaqItem {
  id: string;
  question: string;
  answer: string;
  category?: HelpGuideCategory | 'general';
}

export interface TrainingGuide {
  id: string;
  title: string;
  category: HelpGuideCategory;
  summary: string;
  /** Primary workspace route for this guide. */
  primaryRoute: string;
  /** Optional CTA button label (defaults to “Open — {title}”). */
  ctaLabel?: string;
  /** Additional routes that should surface this guide in the page banner. */
  relatedRoutes?: string[];
  steps: string[];
  tips?: string[];
}

