const normalizePath = (pathname: string) => {
  let path = (pathname || '/').split('?')[0].split('#')[0];
  if (path.length > 1 && path.endsWith('/')) {
    return path.slice(0, -1);
  }
  return path;
};

const pathMatchesGuide = (pathname: string, guide: TrainingGuide): boolean => {
  const path = normalizePath(pathname);
  if (path === guide.primaryRoute || path.startsWith(`${guide.primaryRoute}/`)) {
    return true;
  }
  return (guide.relatedRoutes || []).some(
    (route) => path === route || path.startsWith(`${route}/`)
  );
};

/** Best matching training guide for the current route (primary route beats related routes). */
export function resolveTrainingGuideForPath(pathname: string): TrainingGuide | null {
  const path = normalizePath(pathname);
  let best: TrainingGuide | null = null;
  let bestScore = -1;

  TRAINING_GUIDES.forEach((guide) => {
    if (!pathMatchesGuide(path, guide)) {
      return;
    }

    const primaryMatches =
      path === guide.primaryRoute || path.startsWith(`${guide.primaryRoute}/`);
    const relatedMatches = (guide.relatedRoutes || []).filter(
      (route) => path === route || path.startsWith(`${route}/`)
    );

    let score = 0;
    if (primaryMatches) {
      score = 1000 + guide.primaryRoute.length;
    } else if (relatedMatches.length > 0) {
      score = Math.max(...relatedMatches.map((route) => route.length));
    }

    if (score > bestScore) {
      best = guide;
      bestScore = score;
    }
  });

  return best;
}

export function buildHelpGuideUrl(guideId: string): string {
  return `/help#guide-${guideId}`;
}

export function getTrainingGuidesByCategory(): Array<{
  category: HelpGuideCategory;
  label: string;
  guides: TrainingGuide[];
}> {
  const order: HelpGuideCategory[] = [
    'getting-started',
    'data',
    'carbon',
    'compliance',
    'reporting',
    'finance',
    'enterprise',
  ];

  return order.map((category) => ({
    category,
    label: HELP_GUIDE_CATEGORY_LABELS[category],
    guides: TRAINING_GUIDES.filter((guide) => guide.category === category),
  }));
}
